'use strict';
const $=s=>document.querySelector(s),M=InventoryCost,product=(new URLSearchParams(location.search).get('id')||'').toLowerCase(),owner=KashierData.userId(),key='kashier.inventory-cost.pending.v1.'+owner+'.'+product;
let snapshot=null,pending=null,busy=false,blocked=false,request=0,selectedCancel=null;
const active=()=>Boolean(owner)&&KashierData.loggedIn()&&KashierData.userId()===owner;
function node(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);return e;}
function status(v){$('#cost-status').textContent=v;}
function controls(){const lock=blocked||busy||Boolean(pending)||!snapshot||!active();for(const id of ['total','note','confirmed','save'])$('#cost-'+id).disabled=lock||!snapshot?.canConfirm;for(const e of document.querySelectorAll('[data-cost-cancel]'))e.disabled=lock;$('#cost-reason').disabled=$('#cost-cancel-save').disabled=lock;$('#cost-cancel-close').disabled=busy;$('#cost-refresh').disabled=busy;$('#cost-retry').hidden=!pending;$('#cost-retry').disabled=busy||!active();}
function invalidate(){request++;snapshot=null;$('#cost-content').hidden=true;$('#cost-history').replaceChildren();for(const id of ['name','quantity','value','scope','availability','cancel-summary'])$('#cost-'+id).textContent='';for(const id of ['total','note','reason'])$('#cost-'+id).value='';$('#cost-confirmed').checked=false;selectedCancel=null;if($('#cost-cancel-dialog').open)$('#cost-cancel-dialog').close();controls();}
function render(){const s=snapshot;$('#cost-name').textContent=s.data.product.name;$('#cost-quantity').textContent=M.quantity(s.data.product.quantity_units);$('#cost-value').textContent=s.value===null?'تێچوو نادیارە':M.money(s.value.toString());$('#cost-scope').textContent='کاتی پشکنین: '+s.data.generated_at+' · کۆتا جووڵە: '+s.data.product.stock_version;$('#cost-availability').textContent=s.canConfirm?'بەهای کۆی '+M.quantity(s.data.product.quantity_units)+' یەکەی بەردەست بنووسە؛ نرخی دانە نییە.':s.units===0n?'ستۆک بەتاڵە؛ بنەمای تێچووی نوێ پێویست نییە.':'تێچوو پێشتر دیارە؛ ئەم بەشە تەنها بۆ تێچووی نادیارە.';for(const b of s.history){const row=node('tr'),action=node('td');if(b.canCancel){const button=node('button','هەڵوەشاندنەوە');button.setAttribute('data-cost-cancel','');button.addEventListener('click',()=>{if(blocked||busy||pending||!active())return;selectedCancel=b.id;$('#cost-reason').value='';$('#cost-cancel-summary').textContent=M.quantity(b.quantity_units)+' یەکە · '+M.money(b.total_value)+' دینار';$('#cost-cancel-dialog').showModal();});action.append(button);}row.append(node('td',new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(b.created_at))),node('td',M.quantity(b.quantity_units)),node('td',M.money(b.total_value)),node('td',b.note),node('td',b.cancelled?'هەڵوەشاوە: '+b.cancel_reason:b.canCancel?'هێشتا جووڵەی نوێ ڕووی نەداوە':'لە جووڵەکانی دواتردا بەکارهاتووە'),action);$('#cost-history').append(row);}$('#cost-empty').hidden=s.history.length!==0;$('#cost-content').hidden=false;controls();}
async function load(){invalidate();const mine=++request;if(!active()){location.replace('auth.html?next='+encodeURIComponent('inventory-cost.html?id='+product));return;}if(!M.uuid(product)){status('ناسنامەی کاڵا نادروستە.');return;}status('پشکنینی تێچوو و بڕی کۆگا…');try{const data=await KashierData.getInventoryCostBasis(product);if(mine!==request)return;if(!active())throw Error('هەژمارەکە گۆڕاوە.');snapshot=M.validate(data,product,owner);render();status(blocked?'داواکاری پارێزراو نەخوێندرایەوە؛ پێش کردارێکی نوێ مێژووەکە بپشکنە.':pending?'داواکارییەکی ماوە هەیە؛ هەمان داواکاری بپشکنەوە.':'دۆخی تێچوو خوێندرایەوە.');}catch(e){if(mine===request){invalidate();status(e.message);}}finally{controls();}}
function validPending(p){try{if(p?.version!==1||p.owner!==owner||!['confirm','cancel'].includes(p.kind)||!M.uuid(p.payload?.p_id)||p.payload.p_product!==product)return false;const x=p.payload;if(p.kind==='cancel')return M.uuid(x.p_basis)&&typeof x.p_reason==='string'&&x.p_reason.trim().length>0&&x.p_reason.length<=500;return M.integer(x.p_expected_units,1000000000000n)>0n&&M.integer(x.p_expected_version,9223372036854775807n)>=0n&&M.integer(x.p_total)>=0n&&typeof x.p_note==='string'&&x.p_note.trim().length>0&&x.p_note.length<=500;}catch{return false;}}
function persist(p){try{sessionStorage.setItem(key,JSON.stringify(p));return true;}catch{status('داواکاری نەپارێزرا؛ هیچ کردارێک نەنێردرا.');return false;}}
function clearPending(){try{sessionStorage.removeItem(key);}catch{blocked=true;}pending=null;}
const messages={basis_stock_changed:'بڕ یان جووڵەی کۆگا گۆڕاوە؛ بڕە نوێیەکە دووبارە پشکنە.',basis_cost_already_known:'تێچوو پێشتر دیاری کراوە؛ مێژووەکە بپشکنە.',basis_used_by_movement:'دوای ئەم بنەمایە جووڵەی کاڵا ڕوویداوە؛ ناتوانرێت هەڵبوەشێندرێتەوە.',basis_already_cancelled:'ئەم بنەمایە پێشتر هەڵوەشاوەتەوە.',basis_too_many_records:'سنووری ٢٠٠ تۆماری بنەمای ئەم کاڵایە پڕ بووە.',basis_product_unavailable:'کاڵا نەدۆزرایەوە یان هی ئەم هەژمارە نییە.',basis_invalid_request:'بڕ و بەهای تێچوو نادروستن.',basis_note_required:'بەڵگە یان هۆکارێک تا ٥٠٠ پیت بنووسە.'};
async function send(){if(busy||!pending)return;if(!active()){invalidate();status('هەژمارەکە گۆڕاوە؛ هیچ داواکارییەک نەنێردرا.');return;}const mine=request,item=pending;busy=true;controls();status('تۆمارکردنی بنەمای تێچوو…');try{const result=await(item.kind==='confirm'?KashierData.confirmInventoryCostBasis(item.payload):KashierData.cancelInventoryCostBasis(item.payload));if(mine!==request||!active())return;if(result?.id!==item.payload.p_id||result.product_id!==product||item.kind==='confirm'&&result.total_value!==item.payload.p_total)throw Error('وەڵامی داواکاری پشتڕاست نەکرایەوە.');clearPending();busy=false;await load();if(snapshot&&!blocked)status('کردار تۆمار کرا؛ بڕی کۆگا، سندوق و قەرز نەگۆڕان.');}catch(e){if(mine!==request||!active())return;if(Object.hasOwn(messages,e.saleCode)){clearPending();busy=false;await load();status(messages[e.saleCode]);}else status('دۆخی داواکاری پشتڕاست نییە؛ تەنها هەمان داواکاری بپشکنەوە بۆ ڕێگریکردن لە دووبارەبوونەوە.');}finally{busy=false;controls();}}
$('#cost-form').addEventListener('submit',e=>{e.preventDefault();if(blocked||busy||pending||!snapshot?.canConfirm||!active()||!$('#cost-confirmed').checked||!$('#cost-form').reportValidity())return;try{const total=M.input($('#cost-total').value),note=$('#cost-note').value.trim();if(!note||note.length>500)throw Error('بەڵگە یان هۆکارێک تا ٥٠٠ پیت بنووسە.');const item={version:1,owner,kind:'confirm',payload:{p_id:crypto.randomUUID(),p_product:product,p_expected_units:snapshot.data.product.quantity_units,p_expected_version:snapshot.data.product.stock_version,p_total:total,p_note:note}};if(!persist(item))return;pending=item;send();}catch(error){status(error.message);}});
$('#cost-cancel-form').addEventListener('submit',e=>{e.preventDefault();if(blocked||busy||pending||!snapshot||!active()||!selectedCancel||!$('#cost-cancel-form').reportValidity())return;const reason=$('#cost-reason').value.trim();if(!reason||reason.length>500){status('هۆکارێک تا ٥٠٠ پیت بنووسە.');return;}const item={version:1,owner,kind:'cancel',payload:{p_id:crypto.randomUUID(),p_product:product,p_basis:selectedCancel,p_reason:reason}};if(!persist(item))return;pending=item;send();});
$('#cost-refresh').addEventListener('click',load);$('#cost-retry').addEventListener('click',send);$('#cost-cancel-close').addEventListener('click',()=>{if(!busy)$('#cost-cancel-dialog').close();});$('#cost-cancel-dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault();});if(M.uuid(product))$('#cost-product').href='product.html?id='+product;
try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved){if(!validPending(saved))throw Error();pending=saved;}}catch{blocked=true;}
window.addEventListener('pagehide',invalidate);window.addEventListener('pageshow',e=>{if(e.persisted){invalidate();location.reload();}});load();
